/**
 * @file
 * @brief Serves the embedded web page.
 */
#include "webui/webui.h"
#include <string.h>

/* Generated by the Makefile from index.html: `static const unsigned char webui_index_html[]`. */
#include "webui/page_data.h"

bool
webui_serve(const char* path, u32 path_len, const u8** body, u32* len, const char** content_type)
{
	if (!((path_len == 1 && path[0] == '/') ||
	      (path_len == 11 && memcmp(path, "/index.html", 11) == 0)))
		return false;
	*body         = webui_index_html;
	*len          = (u32)sizeof(webui_index_html);
	*content_type = "text/html; charset=utf-8";
	return true;
}
